"use client";

import React from "react";
import { workExp } from "@/src/utils/data";
import { motion } from "framer-motion";
import { fadeIn, staggerChildren, textVariant2, zoomIn } from "@/src/utils/motion";

const Work = () => {
  return (
    <motion.section
      variants={staggerChildren}
      initial="hidden"
      whileInView="show"
      viewport={{ once: false, amount: 0.03 }}
      className="bg-cover bg-center bg-no-repeat px-4 py-16 md:px-8 lg:px-16"
      style={{
        backgroundImage:
          "url('https://res.cloudinary.com/dtiaycw2o/image/upload/v1756199687/home-bg-2_mekdvx.webp')",
      }}
    >
      <a className="block" id="work" />

      <div className="max-w-6xl mx-auto flex flex-col items-center gap-8">

        {/* Heading */}
        <span className="text-2xl md:text-4xl font-bold text-[#5e317e] py-4">
          Our Premium Service
        </span>

        {/* ── Mobile: stacked cards ── */}
        <div className="flex flex-col gap-4 w-full md:hidden">
          {workExp.map((exp, i) => (
            <motion.div
              key={i}
              variants={textVariant2}
              className="bg-white/85 backdrop-blur-sm rounded-xl p-4 shadow-sm"
            >
              {/* Service label + name */}
              <span className="inline-block text-[11px] font-semibold
                bg-[#fde8e8] text-[#950a25] px-3 py-1 rounded-full mb-2">
                Service
              </span>
              <h2 className="text-[#950a25] text-base font-bold mb-2">
                {exp.place}
              </h2>
              <p className="text-black text-sm mb-3">{exp.tenure}</p>

              <div className="h-px bg-gray-100 mb-3" />

              {/* Role label + detail */}
              <span className="inline-block text-[11px] font-semibold
                bg-[#e8f5e9] text-[#1b5e20] px-3 py-1 rounded-full mb-2">
                Benefit
              </span>
              <h3 className="text-gray-800 text-sm font-semibold mb-1">
                {exp.role}
              </h3>
              <p className="text-gray-800 text-sm leading-relaxed">
                {exp.detail}
              </p>
            </motion.div>
          ))}
        </div>

        {/* ── Desktop: original timeline layout ── */}
        <div className="hidden md:flex w-full flex-col gap-6 relative">
          {workExp.map((exp, i) => (
            <motion.div
              key={i}
              variants={textVariant2}
              className="w-full flex justify-between items-start leading-[40px] text-[1.05rem]"
            >
              <div className="flex-1">
                <h1 className="text-[#950a25] text-[1.5rem] font-semibold">
                  {exp.place}
                </h1>
                <p className="text-black">{exp.tenure}</p>
              </div>
              <div className="flex-1 ml-8">
                <h1 className="text-[#950a25] text-[1.5rem] font-semibold">
                  {exp.role}
                </h1>
                <p className="text-gray-800">{exp.detail}</p>
              </div>
            </motion.div>
          ))}

          {/* Progress bar — desktop only */}
          <motion.div
            variants={zoomIn(1, 1)}
            className="absolute h-full flex flex-col gap-6"
            style={{ left: "45%" }}
          >
            <motion.div
              variants={fadeIn("down", "tween", 2, 1.5)}
              className="absolute h-[92%] w-[2px] z-[1] rounded-[5px]"
              style={{
                backgroundImage:
                  "linear-gradient(black 33%, rgba(255,255,255,0) 0%)",
                backgroundPosition: "right",
                backgroundSize: "2px 30px",
                backgroundRepeat: "repeat-y",
                left: "48%",
              }}
            />
            <div className="flex-1 pt-3 z-[2]">
              <div className="rounded-full w-5 h-5" style={{ background: "#286F6C" }} />
            </div>
            <div className="flex-1 pt-3 z-[2]">
              <div className="rounded-full w-5 h-5" style={{ background: "#F2704E" }} />
            </div>
            <div className="flex-1 pt-3 z-[2]">
              <div className="rounded-full w-5 h-5" style={{ background: "purple" }} />
            </div>
          </motion.div>
        </div>

      </div>
    </motion.section>
  );
};

export default Work;