"use client";

import Image from "next/image";
import Link from "next/link";

const Welcome = () => {
  return (
    <section className="text-center px-4 py-8 md:px-6 lg:px-8 bg-white">

      {/* Header */}
      <div className="mt-10 mb-16 md:mb-20">
        <p className="text-lg md:text-xl font-semibold text-[#333333]">
          Welcome to Lovely Looks!!!
        </p>
        <h1 className="text-3xl md:text-4xl lg:text-5xl font-bold text-black mt-2">
          Where Beauty{" "}
          <span className="text-[#5b0996]">Meets Indulgence</span> !!
        </h1>
        <p className="mt-4 text-sm md:text-base text-gray-800 max-w-2xl mx-auto">
          Lovely Looks brings a fresh perspective to the beauty parlour
          experience by offering personalized services for Hair, Skin, Nail,
          Body, and Face.
        </p>
      </div>

      {/* Cards */}
      <div className="flex flex-wrap justify-center gap-6 md:gap-8">

        {/* Card 1 */}
        <div className="relative w-full sm:w-[calc(50%-1rem)] max-w-[550px]
          h-[140px] sm:h-[220px] md:h-[250px]
          rounded-[10px] overflow-hidden shadow-md">
          <Image
            src="https://res.cloudinary.com/dtiaycw2o/image/upload/v1756199686/card2_t5asqq.webp"
            alt="Hair and skin services at Lovely Looks beauty parlour"
            fill
            sizes="(max-width: 640px) 100vw, 550px"
            className="object-cover"
            loading="lazy"
          />
          <Link
            href="/service"
            className="absolute bottom-3 sm:bottom-8 right-1/6 -translate-x-1/2
              bg-[rgb(160,45,160)] hover:bg-[#573477] text-white
              text-xs sm:text-sm md:text-base
              px-3 py-1.5 sm:px-4 sm:py-2
              rounded-[5px] transition-colors duration-200 whitespace-nowrap"
          >
            Explore Now
          </Link>
        </div>

        {/* Card 2 */}
        <div className="relative w-full sm:w-[calc(50%-1rem)] max-w-[550px]
          h-[140px] sm:h-[220px] md:h-[250px]
          rounded-[10px] overflow-hidden shadow-md">
          <Image
            src="https://res.cloudinary.com/dtiaycw2o/image/upload/v1756199685/card1_h3carw.webp"
            alt="Nail and face services at Lovely Looks beauty parlour"
            fill
            sizes="(max-width: 640px) 100vw, 550px"
            className="object-cover"
            loading="lazy"
          />
          <Link
            href="/service"
            className="absolute bottom-1.5 sm:bottom-5 right-1/6 -translate-x-1/2
              bg-[rgb(160,45,160)] hover:bg-[#573477] text-white
              text-xs sm:text-sm md:text-base
              px-3 py-1.5 sm:px-4 sm:py-2
              rounded-[5px] transition-colors duration-200 whitespace-nowrap"
          >
            Explore Now
          </Link>
        </div>

      </div>
    </section>
  );
};

export default Welcome;