"use client";

import React, { useState, useEffect } from "react";
import { projectExperience, WhatDoIHelp } from "@/src/utils/data";
import { motion } from "framer-motion";
import { fadeIn, staggerContainer, textVariant } from "@/src/utils/motion";

const Experties = () => {
  const [makeupCompleted, setMakeupCompleted] = useState(0);
  const [happyClients, setHappyClients] = useState(0);

  const targetMakeups = 1100;
  const targetClients = 1500;

  useEffect(() => {
    const makeupInterval = setInterval(() => {
      setMakeupCompleted((prev) => {
        if (prev < targetMakeups) return prev + 1;
        clearInterval(makeupInterval);
        return prev;
      });
    }, 5);

    const clientInterval = setInterval(() => {
      setHappyClients((prev) => {
        if (prev < targetClients) return prev + 1;
        clearInterval(clientInterval);
        return prev;
      });
    }, 4);

    return () => {
      clearInterval(makeupInterval);
      clearInterval(clientInterval);
    };
  }, []);

  return (
    <section
      className="bg-white bg-cover bg-center bg-no-repeat w-full"
      style={{
        backgroundImage:
          "url('https://res.cloudinary.com/dtiaycw2o/image/upload/v1756199687/home-bg-1_mspklj.webp')",
      }}
    >
      <a className="block" id="experties" />

      <motion.div
        variants={staggerContainer}
        initial="hidden"
        whileInView="show"
        viewport={{ once: false, amount: 0.25 }}
        className="max-w-6xl mx-auto px-4 py-16 flex flex-wrap gap-8 items-start justify-center"
      >

        {/* Left Side */}
        <div className="flex flex-col gap-8 flex-1 min-w-[300px]">
          {projectExperience.map((exp, i) => (
            <motion.div
              key={i}
              variants={fadeIn("right", "tween", (i + 1) * 0.05, 0.3)}
              className="flex items-center gap-8 border border-[coral] rounded-[20px]
                p-6 transition-all duration-200 ease-out hover:shadow-lg hover:cursor-pointer"
            >
              {/* Icon circle */}
              <div
                className="flex items-center justify-center w-20 h-20 rounded-full shrink-0 p-2.5"
                style={{ background: exp.bg }}
              >
                <img
                  src={exp.icon}
                  alt={exp.name}
                  className="w-[45px] h-[45px]"
                />
              </div>

              {/* Text */}
              <div className="flex flex-col gap-3">
                <span className="text-xl font-bold text-black">
                  {exp.name}
                </span>
                <span className="text-gray-800 text-lg">
                  {exp.projects} Reviews
                </span>
              </div>
            </motion.div>
          ))}
        </div>

        {/* Right Side */}
        <motion.div
          variants={textVariant(0.5)}
          className="flex flex-col gap-8 flex-1 min-w-[300px] text-center sm:text-left"
        >
          <span className="text-3xl md:text-3xl font-bold text-[#671d8a] inline-block transition-transform duration-500 ease-out">
            What makes our beauty services unique?
          </span>

          {WhatDoIHelp.map((paragraph, i) => (
            <span key={i} className="text-gray-800 tracking-[0.04rem] text-sm md:text-base leading-relaxed">
              {paragraph}
            </span>
          ))}

          {/* Stats */}
          <div className="flex gap-16 items-start justify-start flex-wrap">
            <div className="flex flex-col items-start gap-1">
              <span className="text-4xl md:text-3xl font-bold text-[#671d8a]">
                {makeupCompleted}+
              </span>
              <span className="text-gray-800 text-sm">Makeup Completed</span>
            </div>
            <div className="flex flex-col items-start gap-1">
              <span className="text-4xl md:text-3xl font-bold text-[#671d8a]">
                {happyClients}+
              </span>
              <span className="text-gray-800 text-sm">Happy Clients</span>
            </div>
          </div>
        </motion.div>

      </motion.div>
    </section>
  );
};

export default Experties;